nta.declaration:
// MAP BOUNDARIES const int MAX_X = 17; // The rightmost cell boundary. const int MAX_Y = 12; // The topmost cell boundary (home bays). const int MIN_X = 0; // The leftmost boundary. const int MIN_Y = 0; // The bottommost boundary.
// INITIAL TIMEOUT const int INITIAL_TIMEOUT = 300;
// FROG int[0, MAX_X] frog_x = 9; // Frogger's current X position. int[0, MAX_Y] frog_y = 0; // Frogger's current Y position. int[-1, 1] frog_dir_x = 0; // (For the Stochastic version) the direction Frogger intends to move. int[-1, 1] frog_dir_y = 0; // (For the Stochastic version) the direction Frogger intends to move.
// GAME PROGRESSION int[0, 5] lives = 5; // The player starts with 5 lives. int score = 0; // Total points scored. int level = 1; // Current game level. int[0, 5] home_bays_filled = 0; // Tracks how many of the 5 bays are occupied. bool bay_occupied[5]; // An array tracking which specific bays are filled (Indices 0 to 4 mapping to the 5 home bay pairs).
// CLOCK clock game_timer; // Tracks the 30-second (or less) countdown. clock time_since_respawn; // Tracks the 2 seconds (20 units) Frogger must wait before moving after dying or scoring.
// DANGER ZONES bool danger[MAX_X + 1][MAX_Y + 1]; // Vehicles update their current footprint to true here. If Frogger is on a true tile, he dies. bool safe_platform[MAX_X + 1][MAX_Y + 1]; // Logs and Turtles update their footprint here. If Frogger is in the river (Y = 7 to 11) and this is false, he drowns.
// CHANNELS broadcast chan jump; // Triggered when Frogger decides to move. broadcast chan die; // Triggered when Frogger touches a vehicle, submerging turtle, or drowns. broadcast chan score_bay; // Triggered when Frogger lands in an empty home bay. broadcast chan new_level; // Triggered when home_bays_filled == 5.

nta.system:
// Place template instantiations here.
Process = Template();
// List one or more processes to be composed into a system.
system Process;
